// ================= PENGATURAN TELEGRAM ================
const TELEGRAM_BOT_TOKEN = "ISI_DENGAN_BOT_TOKEN_ANDA"; // Contoh: 123456789:ABCdef...
const TELEGRAM_CHAT_ID   = "ISI_DENGAN_CHAT_ID_ANDA";   // Contoh: 987654321 atau -100123456789
const COOLDOWN_SECONDS   = 30; // Jeda notifikasi agar tidak spam (detik)
// =====================================================

let count = msg.payload.count;
let isViolation = (count === 1) || msg.payload.violation === true;
let imageBase64 = msg.payload.image;
let timestamp = msg.payload.timestamp || Math.floor(Date.now() / 1000);
let timeStr = new Date(timestamp * 1000).toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });

let lastAlertTime = context.get('lastAlertTime') || 0;
let now = Math.floor(Date.now() / 1000);

if (isViolation) {
    // Cek cooldown
    if (now - lastAlertTime >= COOLDOWN_SECONDS) {
        context.set('lastAlertTime', now);

        let captionText = `🚨 <b>PERINGATAN RUANG GENSET</b> 🚨\n` +
                          `━━━━━━━━━━━━━━━━━━━━━\n` +
                          `⚠️ <b>Pelanggaran Two-Person Rule!</b>\n` +
                          `👤 <b>Jumlah Orang:</b> 1 Orang (Sendirian)\n` +
                          `🕒 <b>Waktu:</b> ${timeStr} WIB\n` +
                          `📍 <b>Lokasi:</b> Generator Room\n` +
                          `━━━━━━━━━━━━━━━━━━━━━\n` +
                          `<i>Segera kirimkan personel pendamping demi keselamatan kerja (K3).</i>`;

        // Jika payload menyertakan screenshot (base64 image)
        if (imageBase64) {
            let boundary = '----WebKitFormBoundary' + Math.random().toString(36).substring(2);
            let imgBuffer = Buffer.from(imageBase64, 'base64');
            let parts = [];

            // Parameter chat_id
            parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="chat_id"\r\n\r\n${TELEGRAM_CHAT_ID}\r\n`));
            // Parameter caption
            parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="caption"\r\n\r\n${captionText}\r\n`));
            // Parameter parse_mode
            parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="parse_mode"\r\n\r\nHTML\r\n`));
            // File photo (multipart binary)
            parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="photo"; filename="snapshot_violation.jpg"\r\nContent-Type: image/jpeg\r\n\r\n`));
            parts.push(imgBuffer);
            parts.push(Buffer.from(`\r\n--${boundary}--\r\n`));

            msg.url = `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendPhoto`;
            msg.headers = { 'Content-Type': `multipart/form-data; boundary=${boundary}` };
            msg.payload = Buffer.concat(parts);
            return msg;
        } else {
            // Fallback pesan teks biasa
            msg.url = `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`;
            msg.headers = { 'Content-Type': 'application/json' };
            msg.payload = {
                chat_id: TELEGRAM_CHAT_ID,
                text: captionText,
                parse_mode: 'HTML'
            };
            return msg;
        }
    } else {
        node.warn(`Pelanggaran terdeteksi tapi masih dalam cooldown (${COOLDOWN_SECONDS}s).`);
        return null;
    }
}

return null;
